import clsx from 'clsx';
import React, { forwardRef, useCallback } from 'react';
import type { ChangeEvent, ComponentProps, KeyboardEvent } from 'react';
import { useComponentContextIcons, useTranslationContext } from '../../context';
import { useStableId } from '../UtilityComponents/useStableId';
import { Button } from '../Button';

export type NumericInputProps = Omit<
  ComponentProps<'input'>,
  'className' | 'type' | 'value' | 'onChange'
> & {
  value: string;
  onChange: (e: ChangeEvent<HTMLInputElement>) => void;
  /** Label above the input. */
  label?: string;
  /** Lower bound that the steppers and arrow keys clamp to. */
  min?: number;
  /** Upper bound that the steppers and arrow keys clamp to. */
  max?: number;
  /** Amount the steppers and arrow keys change the value by. Defaults to 1. */
  step?: number;
  className?: string;
};

const parseNumeric = (s: string): number | null => {
  const trimmed = s.trim();
  if (trimmed === '') return null;
  const n = Number(trimmed);
  return Number.isFinite(n) ? n : null;
};

const clamp = (n: number, min: number, max: number): number =>
  Math.min(Math.max(n, min), max);

export const NumericInput = forwardRef<HTMLInputElement, NumericInputProps>(
  function NumericInput(
    {
      className,
      disabled = false,
      id: idProp,
      label,
      max,
      min,
      onChange,
      step = 1,
      value,
      ...inputProps
    },
    ref,
  ) {
    const { IconMinus, IconPlusSmall } = useComponentContextIcons();
    const generatedId = useStableId();
    const id = idProp ?? generatedId;
    const { t } = useTranslationContext();

    const num = parseNumeric(value);
    const minDef = min ?? -Infinity;
    const maxDef = max ?? Infinity;
    const atMin = num !== null && num <= minDef;
    const atMax = num !== null && num >= maxDef;
    // An empty field steps to `min`, or to 0 when there is no lower bound.
    const emptyValueStep = clamp(min ?? 0, minDef, maxDef);

    const handleInputChange = useCallback(
      (e: ChangeEvent<HTMLInputElement>) => {
        const next = e.target.value;
        if (next === '' || /^\d+$/.test(next)) {
          onChange(e);
        }
      },
      [onChange],
    );

    const createChangeEvent = useCallback(
      (newValue: string): ChangeEvent<HTMLInputElement> =>
        ({
          currentTarget: { value: newValue },
          target: { value: newValue },
        }) as ChangeEvent<HTMLInputElement>,
      [],
    );

    const handleDecrement = useCallback(() => {
      if (disabled || atMin) return;
      const next = num !== null ? clamp(num - step, minDef, maxDef) : emptyValueStep;
      onChange(createChangeEvent(String(next)));
    }, [
      disabled,
      atMin,
      num,
      step,
      minDef,
      maxDef,
      emptyValueStep,
      onChange,
      createChangeEvent,
    ]);

    const handleIncrement = useCallback(() => {
      if (disabled || atMax) return;
      const next = num !== null ? clamp(num + step, minDef, maxDef) : emptyValueStep;
      onChange(createChangeEvent(String(next)));
    }, [
      disabled,
      atMax,
      num,
      step,
      minDef,
      maxDef,
      emptyValueStep,
      onChange,
      createChangeEvent,
    ]);

    const handleKeyDown = useCallback(
      (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'ArrowDown') {
          e.preventDefault();
          handleDecrement();
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          handleIncrement();
        }
      },
      [handleDecrement, handleIncrement],
    );

    return (
      <div
        className={clsx(
          'str-chat__form-numeric-input',
          disabled && 'str-chat__form-numeric-input--disabled',
          className,
        )}
      >
        {!!label && (
          <label className='str-chat__form-numeric-input__label' htmlFor={id}>
            {label}
          </label>
        )}
        <div className={clsx('str-chat__form-numeric-input__wrapper')}>
          <Button
            appearance='outline'
            aria-label={t('form.numericInput.decreaseValue.ariaLabel', 'Decrease value')}
            circular
            className={clsx(
              'str-chat__form-numeric-input__stepper str-chat__form-numeric-input__stepper--decrement',
            )}
            disabled={disabled || atMin}
            onClick={handleDecrement}
            size='xs'
            variant='secondary'
          >
            <IconMinus className='str-chat__form-numeric-input__stepper-icon' />
          </Button>
          <input
            aria-valuemax={Number.isFinite(maxDef) ? maxDef : undefined}
            aria-valuemin={Number.isFinite(minDef) ? minDef : undefined}
            aria-valuenow={num ?? undefined}
            className='str-chat__form-numeric-input__input'
            disabled={disabled}
            id={id}
            inputMode='numeric'
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            ref={ref}
            role='spinbutton'
            size={Math.max(2, value.length)}
            type='text'
            value={value}
            {...inputProps}
          />
          <Button
            appearance='outline'
            aria-label={t('form.numericInput.increaseValue.ariaLabel', 'Increase value')}
            circular
            className={clsx(
              'str-chat__form-numeric-input__stepper str-chat__form-numeric-input__stepper--increment',
            )}
            disabled={disabled || atMax}
            onClick={handleIncrement}
            size='xs'
            variant='secondary'
          >
            <IconPlusSmall className='str-chat__form-numeric-input__stepper-icon' />
          </Button>
        </div>
      </div>
    );
  },
);
